cat > src/cart.js <<'EOF'
// Cart total in cents. `discount` is the customer's discount rate (0.1 = 10%).
// Carts with 10 or more lines get an extra 5% bulk discount, applied once after the customer's discount.
export function total(items, discount = 0) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const bulk = items.length >= 10 ? 0.05 : 0;
  return Math.round(subtotal * (1 - discount) * (1 - bulk));
}

export function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}
EOF
cat >> tests/cart.test.js <<'EOF'

const lines = (n) => Array.from({ length: n }, () => ({ price: 1000, qty: 1 }));

test('AC-1: 10+ lines get customer discount, then 5% bulk discount once', () => {
  // 10000 * 0.9 * 0.95
  assert.equal(total(lines(10), 0.1), 8550);
});

test('AC-2: 9 lines get no bulk discount', () => {
  assert.equal(total(lines(9), 0.1), 8100);
});

test('AC-3: 0% customer still gets bulk discount on 10+ lines', () => {
  assert.equal(total(lines(10), 0), 9500);
});
EOF
